import * as THREE from 'three';
import {createBaseballModel} from './baseball-model.js';
import {createBaseballSession,fitBaseballCamera} from './baseball-session.js';
export const BASEBALL_BODY=`<div class="baseball-layout"><div id="baseball-court" class="baseball-court" tabindex="0" role="img" aria-label="호랑이가 던지는 공과 도름이의 배트"><p id="baseball-call" role="status"></p></div><section class="baseball-panel"><p id="baseball-status" role="status"></p><div id="baseball-score" class="baseball-score" aria-label="다섯 공의 결과"></div><button id="baseball-swing" class="baseball-swing" disabled>타격 · Space</button><p class="baseball-help">공이 흰 원 가까이 오면 한 번 눌러요. 배트 끝의 가운데에 잘 맞으면 홈런!</p><div class="baseball-speed" role="group" aria-label="공의 속도"><button id="baseball-easy" aria-pressed="true">천천히</button><button id="baseball-normal" aria-pressed="false">보통</button></div><div class="baseball-actions"><button id="baseball-start">5구 연습 시작</button><button id="baseball-pause" hidden>잠깐 쉬기</button><button id="baseball-restart" hidden>다시 연습</button></div></section></div>`;
const labels={miss:'헛스윙',hit:'안타',homeRun:'홈런'};
export function createBaseballController({ui,getView,getActors,stage,isAllowed=()=>true,reduced=false,doc=globalThis.document,win=globalThis.window,sessionFactory=createBaseballSession,fitCamera=fitBaseballCamera}){
 const camera=new THREE.OrthographicCamera(-7,7,4,-4,.1,120),$=id=>doc.querySelector('#'+id);let live=null,generation=0,speed='easy';
 const listen=(n,t,f)=>{if(n){n.addEventListener(t,f);live.listeners.push([n,t,f]);}};
 function clear(){if(!live)return;live.key=null;live.pointer=null;}
 function render(){if(!live)return;const s=live.model.snapshot(),done=s.complete,call=s.paused?'잠깐 쉬어요':s.phase==='ready'?'배트를 들고, 준비!':done?'다섯 공, 끝!':s.phase==='result'?(s.outcome==='miss'&&!s.hasSwung?'놓쳤어요':labels[s.outcome]):s.phase==='windup'?'호랑이가 준비해요':s.hasSwung?'휘익!':'공을 봐요!';$('baseball-call').textContent=call;$('baseball-status').textContent=s.paused?'계속하기를 누르면 이어져요':done?`안타 ${s.results.filter(r=>r==='hit').length} · 홈런 ${s.results.filter(r=>r==='homeRun').length}`:s.phase==='ready'?'속도를 고르고 5구를 함께 연습해요':`${s.pitch} / 5번째 공${s.phase==='result'?s.outcome==='miss'?' · 다음 공도 괜찮아요':s.outcome==='homeRun'?' · 담장 너머로!':' · 배트에 맞았어요':''}`;$('baseball-score').textContent=Array.from({length:5},(_,i)=>s.results[i]?`${i+1} ${labels[s.results[i]]}`:`${i+1} ·`).join('　');$('baseball-swing').disabled=s.phase!=='flight'||s.hasSwung||s.paused;$('baseball-start').hidden=s.phase!=='ready';$('baseball-pause').hidden=['ready','complete'].includes(s.phase);$('baseball-pause').textContent=s.paused?'계속하기':'잠깐 쉬기';$('baseball-restart').hidden=!done&&!s.paused;for(const mode of['easy','normal']){$('baseball-'+mode).setAttribute('aria-pressed',String(mode===speed));$('baseball-'+mode).disabled=!['ready','complete'].includes(s.phase);} }
 function observe(dt=0){if(!live)return;const s=live.model.snapshot();live.session.update(s,reduced,dt);render();}
 function pause(){if(!live)return;clear();live.model.pause();observe();}
 function clean(token){if(!live||token!==generation)return;const old=live;clear();live=null;generation++;old.observer?.disconnect();for(const[n,t,f]of old.listeners)n.removeEventListener(t,f);try{old.session.dispose();}finally{stage.classList.remove('baseball-open');doc.body?.classList.remove('baseball-open');}}
 function close(){if(!live)return;clean(generation);ui.close();}
 function open(){if(live||!isAllowed())return false;const source=getView();if(!source?.root)return false;const token=++generation;return ui.workshop('호랑이와 타격 연습',BASEBALL_BODY,()=>{let session;try{session=sessionFactory({view:source,...getActors()});live={source,session,model:createBaseballModel({release:session.release,speed}),listeners:[],key:null,pointer:null};stage.classList.add('baseball-open');doc.body?.classList.add('baseball-open');const act=(id,f)=>listen($(id),'click',e=>{if(!live||token!==generation)return;e.preventDefault();f();});const start=()=>{clear();live.model.reset({speed});live.model.start();observe();$('baseball-court').focus();};act('baseball-start',start);act('baseball-restart',start);act('baseball-pause',()=>{if(doc.hidden)return;if(live.model.snapshot().paused){clear();live.model.resume();observe();$('baseball-court').focus();}else pause();});for(const mode of['easy','normal'])act('baseball-'+mode,()=>{if(!['ready','complete'].includes(live.model.snapshot().phase))return;speed=mode;live.model.reset({speed});observe();});
  const button=$('baseball-swing');listen(button,'pointerdown',e=>{if(!live||e.button!==0||e.isPrimary===false||live.pointer!==null||button.disabled)return;e.preventDefault();live.pointer=e.pointerId;button.setPointerCapture?.(e.pointerId);live.model.swing();observe();});for(const type of['pointerup','pointercancel','lostpointercapture'])listen(button,type,e=>{if(live?.pointer===e.pointerId)live.pointer=null;});listen(button,'click',e=>{e.preventDefault();if(live&&e.detail===0&&!live.key&&live.pointer===null){live.model.swing();observe();}});
  listen(doc,'keydown',e=>{if(!live||e.defaultPrevented||!['Space','Enter'].includes(e.code)||e.code==='Enter'&&e.target?.id!=='baseball-swing'||e.ctrlKey||e.metaKey||e.altKey||['INPUT','SELECT','TEXTAREA'].includes(e.target?.tagName)||e.target?.tagName==='BUTTON'&&e.target.id!=='baseball-swing')return;e.preventDefault();if(e.repeat||live.key)return;live.key=e.code;live.model.swing();observe();});listen(doc,'keyup',e=>{if(live&&e.code===live.key)live.key=null;});listen(win,'blur',pause);listen(doc,'visibilitychange',()=>{if(doc.hidden)pause();});const resize=()=>{if(live)viewport(stage.clientWidth||350,stage.clientHeight||640);};listen(win,'resize',resize);if(win.visualViewport)listen(win.visualViewport,'resize',resize);if(typeof ResizeObserver==='function'){live.observer=new ResizeObserver(resize);live.observer.observe($('baseball-court'));}observe();resize();$('baseball-court').focus();return()=>clean(token);
 }catch{if(live)clean(token);else session?.dispose();ui.close();ui.toast('타격 연습을 준비하지 못했어요. 다시 열어 주세요');}}, {kind:'baseball-workshop',closeLabel:'나가기'});}
 function viewport(width,height){if(!live)return{x:0,y:0,width,height};const b=$('baseball-court').getBoundingClientRect(),base=stage.getBoundingClientRect(),x=Math.max(0,b.left-base.left),y=Math.max(0,b.top-base.top),r={x,y,width:Math.max(1,Math.min(b.width,width-x)),height:Math.max(1,Math.min(b.height,height-y))};fitCamera(camera,live.source.root,r);return r;}
 return{open,close,cancel:close,pause,camera,viewport,tick(dt){if(live){live.model.advance(dt);observe(dt);}},get active(){return!!live;},snapshot:()=>live?.model.snapshot()??null};
}
